def check_coloring(N, M):
    # Colors are represented by integers 0 to M-1
    cube = {}

    # 1. Color the cube based on the sum modulo M
    for x in range(1, N + 1):
        for y in range(1, N + 1):
            for z in range(1, N + 1):
                color = (x + y + z) % M
                cube[(x, y, z)] = color

    # 2. Define slices and check color sets

    # Helper to get the set of colors in a slice
    def get_slice_colors(fixed_coord, fixed_value, axis):
        colors = set()
        if axis == 'x':
            # Slice at x = fixed_value
            for y in range(1, N + 1):
                for z in range(1, N + 1):
                    colors.add(cube[(fixed_value, y, z)])
        elif axis == 'y':
            # Slice at y = fixed_value
            for x in range(1, N + 1):
                for z in range(1, N + 1):
                    colors.add(cube[(x, fixed_value, z)])
        elif axis == 'z':
            # Slice at z = fixed_value
            for x in range(1, N + 1):
                for y in range(1, N + 1):
                    colors.add(cube[(x, y, fixed_value)])
        return colors

    # Check all X slices
    x_sets = [get_slice_colors(0, i, 'x') for i in range(1, N + 1)]

    # Check all Y slices
    y_sets = [get_slice_colors(0, i, 'y') for i in range(1, N + 1)]

    # Check all Z slices
    z_sets = [get_slice_colors(0, i, 'z') for i in range(1, N + 1)]

    # The constraint requires all 27 slices to share the exact same set of colors.
    target_set = x_sets[0]

    all_match = True
    for s in x_sets[1:]:
        if s != target_set:
            all_match = False
            break
    if all_match:
        for s in y_sets:
            if s != target_set:
                all_match = False
                break
    if all_match:
        for s in z_sets:
            if s != target_set:
                all_match = False
                break

    if not all_match:
        return False, None

    # If successful, return the number of distinct colors used in the cube (M) and the size of the slice color set (K)
    # The number of distinct colors used is M, provided M is the target.
    return True, len(target_set)

# Test M=7 (N=3)
